// 76 identity-scene additions: 2 standard + 26 project-selected reworks + 48 myth.
// Edition/sourceNote are data, not claims that a 2026 physical box was inspected.
const wiki = name => `https://sanguosha.fandom.com/zh/wiki/${encodeURIComponent(name)}`;
const REFERENCE_NOTE = '按 Wiki 身份场及分包参考表归纳；实体最新印次未逐卡核验，不混入国战技能。';
function g(id, name, baseName, faction, hp, gender, title, pack, skills, extra = {}) {
  return { id, name, baseName, faction, hp, gender, title, pack,
    skills: skills.map(([name, text]) => ({ name, text })),
    source: wiki(baseName),
    edition: pack === 'standard' ? '标准2013（27将范围）' : pack === 'jie' ? '界限突破·标（26将项目范围）' : '神话再临·身份场参考',
    sourceNote: REFERENCE_NOTE, ...extra };
}

